    where: { cemevi: 'Cemevi', miqat: 'Mizgefta Mîqatê', haram: 'Mescîdul-Heram · Mekke', masa: 'Mes’a · di navbera Safa û Merweyê de', mina: 'Mîna', arafat: 'Erefat', muzdalifa: 'Muzdelîfe', jamarat: 'Cemerat · Mîna' },
